type IntegrationIconType = (typeof integrations)[number]["icon"];

const FIGMA_ICON_BASE = "/leros/assets/icons/figma/";

function FigmaIcon({
  file,
  className = "",
}: {
  file: string;
  className?: string;
}) {
  return (
    <Image
      aria-hidden="true"
      alt=""
      className={`integration-icon figma-svg-icon ${className}`}
      height={64}
      src={`${FIGMA_ICON_BASE}${file}`}
      unoptimized
      width={64}
    />
  );
}

function IntegrationIcon({ type }: { type: IntegrationIconType }) {
  const brandIconProps = {
    "aria-hidden": true,
    className: "integration-icon simple-icon",
    color: "default",
    size: 44,
  } as const;
  const lineIconProps = {
    "aria-hidden": true,
    className: "integration-icon line-icon",
    strokeWidth: 2.8,
  } as const;

  switch (type) {
    case "slack":
      return <FigmaIcon className="icon-slack" file="slack.svg" />;
    case "markdown":
      return (
        <SiMarkdown
          {...brandIconProps}
          className="integration-icon simple-icon icon-markdown"
        />
      );
    case "google-docs":
      return (
        <SiGoogledocs
          {...brandIconProps}
          className="integration-icon simple-icon icon-google-docs"
        />
      );
    case "html":
      return (
        <SiHtml5
          {...brandIconProps}
          className="integration-icon simple-icon icon-html"
        />
      );
    case "web":
      return (
        <SiGooglechrome
          {...brandIconProps}
          className="integration-icon simple-icon icon-web"
        />
      );
    case "voice":
      return (
        <SiFishaudio
          {...brandIconProps}
          className="integration-icon simple-icon icon-voice"
        />
      );
    case "github":
      return (
        <SiGithub
          {...brandIconProps}
          className="integration-icon simple-icon icon-github"
        />
      );
    case "csv":
      return (
        <FileChartColumnIncreasing
          {...lineIconProps}
          className="integration-icon line-icon icon-csv"
        />
      );
    case "google-sheets":
      return (
        <SiGooglesheets
          {...brandIconProps}
          className="integration-icon simple-icon icon-google-sheets"
        />
      );
    case "folder":
      return (
        <Folder
          {...lineIconProps}
          className="integration-icon line-icon icon-folder"
        />
      );
  }
}

