function Hero() {
  const root = useRef<HTMLElement>(null);

  useGSAP(
    () => {
      const mm = gsap.matchMedia();
      mm.add(
        {
          desktop: "(min-width: 768px)",
          reduce: "(prefers-reduced-motion: reduce)",
        },
        (context: { conditions?: { desktop?: boolean; reduce?: boolean } }) => {
          if (context.conditions?.reduce) return;
          if (!context.conditions?.desktop) {
            gsap.from(".hero-final-copy, .hero-lero, .hero-stars", {
              autoAlpha: 0,
              y: 28,
              stagger: 0.12,
              duration: 0.9,
            });
            return;
          }

          gsap.set(".hero-stage-copy", { autoAlpha: 0, y: 30 });
          gsap.set(
            ".tool-pill, .owner-badge, .team-hub, .team-network, .team-node, .hero-orbit, .orbit-agent, .workspace-window",
            {
              autoAlpha: 0,
            },
          );
          gsap.set(".hero-final-copy, .hero-stars", {
            autoAlpha: 1,
            y: 0,
          });
          gsap.set(".hero-lero", {
            autoAlpha: 1,
            x: 0,
            y: 0,
            xPercent: -50,
            yPercent: -50,
            scale: 1,
          });
          gsap.set(".hero-glow", {
            x: 0,
            y: 0,
            scale: 1,
            autoAlpha: 1,
          });
          gsap.set(".team-node", {
            scale: 0.4,
          });
          gsap.set(".team-hub", {
            scale: 0.72,
          });
          gsap.set(".hero-orbit", {
            y: 32,
            scale: 0.84,
          });
          gsap.set(".orbit-agent", {
            scale: 0.72,
          });
          gsap.set(".workspace-window", {
            y: 50,
            scale: 0.9,
          });
          gsap.set(".tool-pill", {
            scale: 0.7,
          });
          gsap.set(".team-line", {
            strokeDashoffset: 140,
          });
          gsap.set(".stage-1, .stage-2, .stage-3", {
            autoAlpha: 0,
            y: 30,
          });

          const idleFloat = gsap.timeline({
            repeat: -1,
            yoyo: true,
            defaults: { duration: 1.7, ease: "sine.inOut" },
          });
          idleFloat
            .to(".hero-lero-body, .hero-lero-face", { y: -22 }, 0)
            .to(".hero-glow", { scale: 1.1, autoAlpha: 0.98 }, 0)
            .to(
              ".hero-stars span",
              {
                y: (index) => (index % 2 === 0 ? -8 : 8),
                autoAlpha: (index) => (index % 3 === 0 ? 0.35 : 0.82),
                stagger: { each: 0.03, from: "random" },
              },
              0,
            );

          let idlePaused = false;
          const tl = gsap.timeline({
            scrollTrigger: {
              trigger: root.current,
              start: "top top",
              end: "+=3600",
              pin: true,
              scrub: 0.7,
              onUpdate: (self) => {
                if (self.progress > 0.025 && !idlePaused) {
                  idlePaused = true;
                  idleFloat.pause(0);
                  gsap.set(".hero-lero-body, .hero-lero-face", { y: 0 });
                  gsap.set(".hero-stars span", { y: 0 });
                } else if (self.progress <= 0.025 && idlePaused) {
                  idlePaused = false;
                  idleFloat.play(0);
                }
              },
            },
          });
          tl.addLabel("intro", 0)
            .addLabel("mine", 0.72)
            .addLabel("team", 1.82)
            .addLabel("space", 2.72)
            .to(
              ".hero-final-copy",
              { autoAlpha: 0, y: -34, duration: 0.4 },
              0.35,
            )
            .to(".hero-stars", { autoAlpha: 0, duration: 0.35 }, 0.4)
            .to(
              ".hero-lero",
              {
                x: "14vw",
                y: "-42vh",
                scale: 0.72,
                duration: 0.65,
                ease: "power2.inOut",
              },
              0.4,
            )
            .to(
              ".hero-glow",
              {
                scale: 1.18,
                autoAlpha: 0.78,
                duration: 0.65,
                ease: "power2.inOut",
              },
              0.4,
            )
            .to(".stage-1", { autoAlpha: 1, y: 0, duration: 0.45 }, "mine")
            .to(".owner-badge", { autoAlpha: 1, duration: 0.35 }, "mine+=0.22")
            .to(
              ".tool-pill",
              { autoAlpha: 1, scale: 1, stagger: 0.04, duration: 0.5 },
              "mine+=0.24",
            )
            .to(".stage-1", { autoAlpha: 0, y: -30, duration: 0.45 }, 1.55)
            .to(".owner-badge", { autoAlpha: 0, duration: 0.3 }, 1.58)
            .to(
              ".tool-pill",
              { autoAlpha: 0, scale: 0.7, stagger: 0.02, duration: 0.35 },
              1.58,
            )
            .to(
              ".hero-lero",
              { x: "10vw", y: "-43vh", scale: 0.34, duration: 0.58 },
              1.62,
            )
            .to(
              ".hero-lero",
              { autoAlpha: 0, scale: 0.24, duration: 0.32 },
              "team-=0.12",
            )
            .to(
              ".hero-glow",
              { autoAlpha: 0.34, scale: 0.82, duration: 0.58 },
              1.62,
            )
            .to(".stage-2", { autoAlpha: 1, y: 0, duration: 0.45 }, "team")
            .to(
              ".team-hub",
              { autoAlpha: 1, scale: 1, duration: 0.42 },
              "team+=0.04",
            )
            .to(".team-network", { autoAlpha: 1, duration: 0.32 }, "team+=0.2")
            .to(
              ".team-node",
              { autoAlpha: 1, scale: 1, stagger: 0.06, duration: 0.58 },
              "team+=0.08",
            )
            .to(
              ".team-line",
              { strokeDashoffset: 0, stagger: 0.04, duration: 0.6 },
              "team+=0.2",
            )
            .to(".stage-2", { autoAlpha: 0, y: -30, duration: 0.4 }, 2.55)
            .to(
              ".team-node, .team-network, .team-hub",
              { autoAlpha: 0, scale: 0.8, duration: 0.4 },
              2.55,
            )
            .to(".stage-3", { autoAlpha: 1, y: 0, duration: 0.45 }, "space")
            .to(
              ".hero-orbit",
              {
                autoAlpha: 1,
                y: 0,
                scale: 1,
                duration: 0.68,
                ease: "power2.out",
              },
              "space+=0.02",
            )
            .to(
              ".orbit-agent",
              {
                autoAlpha: 1,
                scale: 1,
                stagger: { each: 0.035, from: "center" },
                duration: 0.52,
                ease: "back.out(1.15)",
              },
              "space+=0.14",
            )
            .to(
              ".hero-lero",
              { autoAlpha: 0, scale: 0.2, duration: 0.4 },
              "space+=0.02",
            )
            .to(
              ".hero-glow",
              { autoAlpha: 0, scale: 0.52, duration: 0.45 },
              "space+=0.02",
            );
        },
        root,
      );
      return () => mm.revert();
    },
    { scope: root },
  );

  const mascot = SITE_BRAND.mascot;

  return (
    <section
      ref={root}
      className="hero"
      aria-label={`${mascot} 与你的 AI 工作区`}
    >
      <div className="hero-inner">
        <div className="hero-copy">
          {heroStages.map((stage) => (
            <div
              key={stage.className}
              className={`hero-stage-copy ${stage.className}`}
            >
              <h2>{stage.title}</h2>
              <p>{withMascot(stage.description, mascot)}</p>
            </div>
          ))}
        </div>

        <div className="hero-visual">
          <div className="hero-glow" />
          <div className="hero-stars" aria-hidden="true">
            {Array.from({ length: 16 }, (_, i) => (
              <span key={i} className={`star-${i}`} />
            ))}
          </div>
          <HeroLero />
          <span className="owner-badge">
            <Image
              src={asset(SITE_ASSETS.avatars.ethan)}
              alt=""
              width={64}
              height={64}
            />
            Ethan&apos;s {mascot}
          </span>
          {toolPills.map((item, i) => (
            <span key={item} className={`tool-pill tool-${i}`}>
              {item}
            </span>
          ))}

          <svg
            className="team-network"
            viewBox="0 0 600 500"
            aria-hidden="true"
          >
            <path className="team-line" d="M300 250 L300 72" />
            <path className="team-line" d="M300 250 L490 175" />
            <path className="team-line" d="M300 250 L430 405" />
            <path className="team-line" d="M300 250 L170 405" />
            <path className="team-line" d="M300 250 L110 175" />
            <circle cx="300" cy="250" r="45" />
          </svg>
          <span className="team-hub" aria-hidden="true">
            <span className="brand-mark">
              <span />
            </span>
          </span>
          {teamNodes.map((node) => (
            <span
              key={node.className}
              className={`team-node ${node.className}`}
            >
              <Image src={asset(node.image)} alt="" width={68} height={68} />
              <Lero color={node.color} />
            </span>
          ))}

          <div className="hero-orbit" aria-hidden="true">
            <svg className="orbit-ring" viewBox="0 0 620 620">
              <circle cx="310" cy="310" r="232" />
              <circle cx="310" cy="310" r="118" />
            </svg>
            <span className="orbit-center">
              <Lero color="#23df83" />
            </span>
            {heroOrbitRoles.map((role) => (
              <span key={role.name} className={`orbit-agent ${role.className}`}>
                <Lero color={role.color} />
                <small>{role.name}</small>
              </span>
            ))}
          </div>

          <div className="workspace-window">
            <div className="workspace-sidebar">
              <Logo />
              <span># marketing</span>
              <span># product</span>
              <span># engineering</span>
            </div>
            <div className="workspace-main">
              <strong>Pro Plan Launch Brief</strong>
              <p>Why we&apos;re launching now</p>
              <span className="highlight-line" />
              <span className="highlight-line short" />
              <div className="workspace-message">
                <Lero />
                <span>
                  <b>Sarah&apos;s {mascot}</b>
                  <br />
                  Drafted the launch plan and social assets.
                </span>
              </div>
              <div className="workspace-message second">
                <Lero color={SITE_THEME.colors.accentPurple} />
                <span>
                  <b>Lara&apos;s {mascot}</b>
                  <br />
                  Ready for review in workspace.
                </span>
              </div>
            </div>
          </div>
        </div>

        <div className="hero-final-copy">
          <h1>
            你的 <em>AI 团队</em>，<br />
            就在 {SITE_BRAND.name}。
          </h1>
          <p>
            为 Agent 原生而造的工作空间——AI 同事全天候运转，边做边学，与你协同。
          </p>
          <div className="hero-actions">
            <a className="button dark" href={SITE_BRAND.nav.signup}>
              立即开始
            </a>
            <a className="button light" href="#meet-lero">
              了解 {SITE_BRAND.name} <span>›</span>
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}

function RevealSection({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  const ref = useRef<HTMLElement>(null);
  useGSAP(
    () => {
      gsap.from(".reveal-item", {
        autoAlpha: 0,
        y: 42,
        duration: 0.85,
        stagger: 0.08,
        ease: "power2.out",
        scrollTrigger: { trigger: ref.current, start: "top 78%", once: true },
      });
    },
    { scope: ref },
  );
  return (
    <section ref={ref} className={className}>
      {children}
    </section>
  );
}

