function IntegrationsSection() {
  const root = useRef<HTMLElement>(null);
  useGSAP(
    () => {
      const mm = gsap.matchMedia();
      mm.add(
        {
          desktop: "(min-width: 768px)",
          motion: "(prefers-reduced-motion: no-preference)",
        },
        (context: { conditions?: { desktop?: boolean; motion?: boolean } }) => {
          if (!context.conditions?.desktop || !context.conditions.motion) {
            gsap.set(".integration-chip, .integration-cta", {
              autoAlpha: 1,
              scale: 1,
            });
            gsap.set(".final-brand-cta", {
              autoAlpha: 0,
              y: 24,
            });
            return;
          }

          gsap.set(".integration-chip", {
            autoAlpha: 1,
            scale: 1,
            x: 0,
            y: 0,
          });
          gsap.set(".integration-cta", {
            autoAlpha: 0,
            scale: 0.68,
            yPercent: -50,
            y: 70,
          });
          gsap.set(".integration-chip b", {
            y: 0,
          });
          gsap.set(".integration-glow", {
            autoAlpha: 0,
            scale: 0.5,
          });
          gsap.set(".final-brand-cta", {
            autoAlpha: 0,
            yPercent: -50,
            y: 62,
            scale: 0.92,
          });

          gsap.to(".integration-chip b", {
            y: (i: number) => (i % 2 ? -12 : 12),
            repeat: -1,
            yoyo: true,
            duration: 2.2,
            stagger: 0.12,
            ease: "sine.inOut",
          });

          const tl = gsap.timeline({
            scrollTrigger: {
              trigger: root.current,
              start: "top top",
              end: "+=3400",
              pin: true,
              scrub: 0.9,
              anticipatePin: 1,
              invalidateOnRefresh: true,
            },
          });

          const converge =
            (axis: "x" | "y") => (_: number, target: Element) => {
              if (!root.current || !(target instanceof HTMLElement)) return 0;
              const sectionRect = root.current.getBoundingClientRect();
              const chipRect = target.getBoundingClientRect();
              const sectionCenter =
                axis === "x" ?
                  sectionRect.left + sectionRect.width / 2
                : sectionRect.top + sectionRect.height / 2;
              const chipCenter =
                axis === "x" ?
                  chipRect.left + chipRect.width / 2
                : chipRect.top + chipRect.height / 2;
              return sectionCenter - chipCenter;
            };

          tl.to(".integration-chip", {
            autoAlpha: 1,
            scale: 1,
            duration: 0.62,
            ease: "none",
          })
            .to(".integration-chip", {
              x: converge("x"),
              y: converge("y"),
              autoAlpha: 0,
              scale: 0.16,
              stagger: { each: 0.018, from: "center" },
              duration: 1,
              ease: "power3.inOut",
            })
            .to(
              ".integration-glow",
              {
                scale: 0.58,
                autoAlpha: 0.82,
                duration: 0.34,
                ease: "power2.out",
              },
              "<+=0.66",
            )
            .to(".integration-glow", {
              autoAlpha: 0.86,
              scale: 0.76,
              duration: 0.38,
              ease: "none",
            })
            .to(".integration-glow", {
              autoAlpha: 0,
              scale: 0.84,
              duration: 0.32,
              ease: "power2.inOut",
            })
            .to(
              ".integration-cta",
              {
                autoAlpha: 1,
                yPercent: -50,
                y: 0,
                scale: 1.05,
                duration: 0.72,
                ease: "power3.out",
              },
              "-=0.04",
            )
            .to(".integration-cta", {
              autoAlpha: 1,
              scale: 1.08,
              duration: 0.62,
              ease: "none",
            })
            .to(".integration-cta", {
              autoAlpha: 0,
              yPercent: -50,
              y: -54,
              scale: 0.92,
              duration: 0.62,
              ease: "power2.inOut",
            })
            .to(
              ".final-brand-cta",
              {
                autoAlpha: 1,
                y: 0,
                yPercent: -50,
                scale: 1,
                duration: 0.78,
                ease: "power3.out",
              },
              "+=0.12",
            )
            .to(".final-brand-cta", {
              autoAlpha: 1,
              duration: 0.72,
              ease: "none",
            });
        },
      );
      return () => mm.revert();
    },
    { scope: root },
  );
  return (
    <section ref={root} className="integrations-section">
      <div className="integration-glow" />
      {integrations.map((item, i) => (
        <div key={item.name} className={`integration-chip chip-${i}`}>
          <b aria-hidden="true">
            <IntegrationIcon type={item.icon} />
          </b>
          <span>{item.name}</span>
        </div>
      ))}
      <div className="integration-cta">
        <p aria-label="More Context">
          <span>Mo</span>
          <span>re</span> <span>Conte</span>
          <span>xt</span>
        </p>
      </div>
      <div className="final-brand-cta">
        <Logo />
        <h2>现在就搭建你的 AI 团队。</h2>
        <a className="button dark" href={SITE_BRAND.nav.signup}>
          免费开始 →
        </a>
      </div>
    </section>
  );
}

